import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Dashboard = ({ token, setToken }) => {
  const [ledgerData, setLedgerData] = useState({
    date: new Date().toISOString().split('T')[0],
    description: '',
    amount: '',
    category: 'expense'
  });
  const [entries, setEntries] = useState([]);
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [uploadFile, setUploadFile] = useState(null);
  const [stats, setStats] = useState({ total: 0, anomalies: 0, normal: 0 });

  useEffect(() => {
    const fetchEntries = async () => {
      try {
        const response = await axios.get('/api/ledger-entries', {
          headers: { Authorization: `Bearer ${token}` }
        });
        setEntries(response.data);

        // Calculate stats
        const total = response.data.length;
        const anomalies = response.data.filter(entry => entry.is_anomaly).length;
        const normal = total - anomalies;
        setStats({ total, anomalies, normal });
      } catch (error) {
        console.error('Failed to fetch entries:', error);
      }
    };
    fetchEntries();
  }, [token]);

  const handleFileUpload = async (e) => {
    e.preventDefault();
    if (!uploadFile) {
      setMessage({ type: 'error', text: 'Please select a file' });
      return;
    }

    setLoading(true);
    setMessage('');

    const formData = new FormData();
    formData.append('file', uploadFile);

    try {
      const response = await axios.post('/api/upload-ledger', formData, {
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'multipart/form-data'
        }
      });

      if (response.data.anomalies_found > 0) {
        setMessage({
          type: 'anomaly',
          text: `File processed! ${response.data.anomalies_found} anomalies detected out of ${response.data.total_entries} entries. Authorities notified.`
        });
      } else {
        setMessage({
          type: 'success',
          text: `File processed successfully! ${response.data.total_entries} entries added, no anomalies detected.`
        });
      }

      setUploadFile(null);
      document.getElementById('fileInput').value = '';

      // Refresh entries
      const entriesResponse = await axios.get('/api/ledger-entries', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(entriesResponse.data);

      // Update stats
      const total = entriesResponse.data.length;
      const anomalies = entriesResponse.data.filter(entry => entry.is_anomaly).length;
      const normal = total - anomalies;
      setStats({ total, anomalies, normal });
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'File upload failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const response = await axios.post('/api/submit-ledger', ledgerData, {
        headers: { Authorization: `Bearer ${token}` }
      });

      if (response.data.anomaly) {
        setMessage({
          type: 'anomaly',
          text: `ANOMALY DETECTED! ${response.data.message} Authority has been notified via email.`
        });
      } else {
        setMessage({
          type: 'success',
          text: response.data.message
        });
      }

      // Reset form
      setLedgerData({
        date: new Date().toISOString().split('T')[0],
        description: '',
        amount: '',
        category: 'expense'
      });

      // Refresh entries
      const entriesResponse = await axios.get('/api/ledger-entries', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEntries(entriesResponse.data);

      // Update stats
      const total = entriesResponse.data.length;
      const anomalies = entriesResponse.data.filter(entry => entry.is_anomaly).length;
      const normal = total - anomalies;
      setStats({ total, anomalies, normal });
    } catch (error) {
      setMessage({
        type: 'error',
        text: error.response?.data?.message || 'Submission failed'
      });
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    setLedgerData({
      ...ledgerData,
      [e.target.name]: e.target.value
    });
  };

  const handleLogout = () => {
    setToken(null);
  };

  return (
    <div className="dashboard">
      <div className="dashboard-header">
        <h1>Anomaly Detection System</h1>
        <button onClick={handleLogout} className="logout-btn">
          Logout
        </button>
      </div>

      {/* Stats Cards */}
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-number">{stats.total}</div>
          <div className="stat-label">Total Entries</div>
        </div>
        <div className="stat-card">
          <div className="stat-number" style={{color: '#e53e3e'}}>{stats.anomalies}</div>
          <div className="stat-label">Anomalies Detected</div>
        </div>
        <div className="stat-card">
          <div className="stat-number" style={{color: '#38a169'}}>{stats.normal}</div>
          <div className="stat-label">Normal Entries</div>
        </div>
      </div>

      {/* Message Display */}
      {message && (
        <div className={message.type === 'anomaly' ? 'anomaly-alert' : 
                       message.type === 'success' ? 'success-message' : 'error'}>
          {message.text}
        </div>
      )}

      {/* File Upload Card */}
      <div className="card upload-card">
        <h2>Upload Ledger File</h2>
        <form onSubmit={handleFileUpload}>
          <div className="form-group">
            <label>Select CSV or Excel File:</label>
            <input
              id="fileInput"
              type="file"
              accept=".csv,.xlsx,.xls"
              onChange={(e) => setUploadFile(e.target.files[0])}
              required
            />
          </div>
          <button type="submit" className="btn" disabled={loading}>
            {loading ? 'Processing...' : 'Upload & Analyze'}
          </button>
        </form>
        <div style={{ marginTop: '1rem', fontSize: '0.9rem', color: '#718096', fontStyle: 'italic' }}>
          <strong>Required columns:</strong> date, description, amount, category
        </div>
      </div>

      {/* Manual Entry Card */}
      <div className="card form-card">
        <h2>Submit Manual Entry</h2>
        <form onSubmit={handleSubmit}>
          <div className="form-row">
            <div className="form-group">
              <label>Date:</label>
              <input
                type="date"
                name="date"
                value={ledgerData.date}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>Category:</label>
              <select
                name="category"
                value={ledgerData.category}
                onChange={handleChange}
                required
              >
                <option value="expense">💸 Expense</option>
                <option value="income">💰 Income</option>
                <option value="transfer">🔄 Transfer</option>
                <option value="investment">📈 Investment</option>
                <option value="loan">🏦 Loan</option>
                <option value="other">📋 Other</option>
              </select>
            </div>
          </div>
          <div className="form-group">
            <label>Description:</label>
            <textarea
              name="description"
              value={ledgerData.description}
              onChange={handleChange}
              required
              placeholder="Enter detailed transaction description..."
            />
          </div>
          <div className="form-group">
            <label>Amount (₹):</label>
            <input
              type="number"
              step="0.01"
              name="amount"
              value={ledgerData.amount}
              onChange={handleChange}
              required
              placeholder="Enter amount in rupees"
            />
          </div>
          <button type="submit" className="btn" disabled={loading}>
            {loading ? 'Processing...' : 'Submit Entry'}
          </button>
        </form>
      </div>

      {/* Entries Table Card */}
      <div className="card entries-card">
        <h2>Transaction History</h2>
        {entries.length === 0 ? (
          <div style={{ textAlign: 'center', padding: '3rem', color: '#718096' }}>
            <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📊</div>
            <p>No entries found. Start by adding your first transaction!</p>
          </div>
        ) : (
          <div className="table-container">
            <table className="entries-table">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>Description</th>
                  <th>Amount</th>
                  <th>Category</th>
                  <th>Status</th>
                  <th>Created</th>
                </tr>
              </thead>
              <tbody>
                {entries.map((entry) => (
                  <tr key={entry.id}>
                    <td>{entry.date}</td>
                    <td>{entry.description}</td>
                    <td>₹{parseFloat(entry.amount).toLocaleString('en-IN', {minimumFractionDigits: 2})}</td>
                    <td style={{ textTransform: 'capitalize' }}>{entry.category}</td>
                    <td>
                      {entry.is_anomaly ? (
                        <span className="anomaly-badge">ANOMALY</span>
                      ) : (
                        <span className="normal-badge">NORMAL</span>
                      )}
                    </td>
                    <td>{new Date(entry.created_at).toLocaleString()}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
